.ds-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 600;
  font-family: inherit;
  border-radius: var(--radius);
  border: 1px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
  white-space: nowrap;
  max-width: 100%;
}
.ds-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.ds-btn-primary {
  background-color: var(--color-copper);
  color: #ffffff;
  border-color: var(--color-copper);
}
.ds-btn-primary:hover:not(:disabled) {
  background-color: #853e1d;
  border-color: #853e1d;
}
@media (max-width: 640px) { .ds-btn { white-space: normal; text-align: center; word-break: break-word; } }
.ds-btn { font-family: var(--font-body); }
.ds-btn:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }

