.ds-input-text, .ds-input-select, .ds-input-textarea {
  display: block;
  width: 100%;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  font-family: inherit;
  color: var(--color-ink);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  transition: border-color 150ms ease;
}
.ds-input-text:focus, .ds-input-select:focus, .ds-input-textarea:focus {
  border-color: var(--color-ink);
  outline: none;
}
.ds-input-text:disabled, .ds-input-select:disabled, .ds-input-textarea:disabled {
  background-color: var(--color-page);
  color: var(--color-muted);
  cursor: not-allowed;
}
.ds-form-label {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-ink);
  margin-bottom: 0.25rem;
}
.ds-input-text { font-family: var(--font-body); }

.ds-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.125rem 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius);
  line-height: 1.4;
  white-space: nowrap;
}
.ds-badge-matched {
  background-color: var(--color-match-subtle);
  color: var(--color-match);
  border: 1px solid var(--color-match-border);
}
.ds-badge { font-family: var(--font-body); }

.ds-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.125rem 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius);
  line-height: 1.4;
  white-space: nowrap;
}
.ds-badge-neutral {
  background-color: var(--color-neutral-bg);
  color: var(--color-neutral-badge);
  border: 1px solid var(--color-neutral-border);
}
.ds-badge { font-family: var(--font-body); }

.ds-nav-links {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.ds-nav-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-muted);
  text-decoration: none;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius);
  transition: color 150ms ease;
}
.ds-nav-link:hover, .ds-nav-link.ds-is-active {
  color: var(--color-ink);
}
.ds-nav-link { font-family: var(--font-body); }
.ds-nav-link:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }

.ds-reconcile-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}
.ds-reconcile-title {
  font-size: 1.0625rem;
  margin: 0;
}
.ds-reconcile-card { font-family: var(--font-body); color: var(--color-ink); }

.ds-source-fields {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.ds-field-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  font-size: 0.8125rem;
  padding-bottom: 0.375rem;
  border-bottom: 1px solid var(--color-border-subtle);
}
.ds-field-label {
  color: var(--color-muted);
  flex-shrink: 0;
}
.ds-field-value {
  min-width: 0;
  color: var(--color-ink);
  text-align: right;
  word-break: break-all;
}
.ds-hash-code {
  font-family: monospace;
  font-size: 0.75rem;
  color: var(--color-muted);
}
.ds-file-name {
  overflow-wrap: anywhere;
  word-break: normal;
}
.ds-source-fields { font-family: var(--font-body); }
